// Seeded random numbers for Emberlight.
//
// The game uses one shared generator so a screenshot staging can replay an
// exact scene: give it a seed and every wisp, sparkle and twinkle lands in
// the same place. Normal play seeds it from the clock.
export function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export class Rng {
  constructor(seed) {
    this.next = mulberry32(seed);
  }

  // Float in [0, 1).
  float() {
    return this.next();
  }

  // Float in [min, max).
  range(min, max) {
    return min + this.next() * (max - min);
  }

  // Integer in [min, max] inclusive.
  int(min, max) {
    return Math.floor(this.range(min, max + 1));
  }

  // Pick one item from an array.
  pick(items) {
    return items[Math.floor(this.next() * items.length)];
  }

  // True with probability p.
  chance(p) {
    return this.next() < p;
  }
}

// A generator seeded from the wall clock, for ordinary play.
export function clockRng() {
  return new Rng((Date.now() ^ Math.floor(Math.random() * 0xffffffff)) >>> 0);
}
